#pragma once
// Exit-time J=1 NTT chain timing diag (FHERMA_J1_DIAG=0: off). Never touches the production module, streams or buffers:
// JIT-loads its own modules (j1_diag.h J1D_PTX / J1D_PTX_PROBE: j1/j1_ntt.cuh + j1/j1_diag_kernels.cuh, NVRTC compute_90
// PTX -> cuModuleLoadData, the production load path; generated by bench/j1diag/mkdiag.py), builds the 118-prime tables on
// the host, fills deterministic residues on the device and times with events (best of 3 repeats of ITERS launches):
//   chain K=118 (1 product; 2 products in two streams), chain K=32, colfwd / row / colinv alone (K=118),
//   the arithmetic-removed probe module (chain + kernels), and the chain + kernels at half occupancy (4 blocks of 128
//   threads per SM = 4 warps per SMSP, forced with dynamic shared memory).
// Lines: {"diag":"j1ntt","k":NAME,"K":..,"us":..,"cyc_per_pt":..,"local_us":..,"local_cyc_per_pt":..}
//   cyc_per_pt = SMSP cycles per residue point = us * clock_khz/1e3 * 4 SMs / (K * 65536 * products), clock_khz =
//   CU_DEVICE_ATTRIBUTE_CLOCK_RATE (as the ovl / issue diags).  A "check" line compares the output checksum of one chain
//   (seeded inputs) with the local RTX 5070 value (the local chain is bit-exact against j1/ref.py).
#include "j1_diag.h"
#include <cuda.h>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <vector>
#include <string>
#include <algorithm>
#include <chrono>
namespace j1d {
typedef unsigned int u32;typedef unsigned long long u64;typedef unsigned __int128 u128;
inline u32 pw(u64 b,u64 e,u64 p){u64 r=1;b%=p;while(e){if(e&1)r=r*b%p;b=b*b%p;e>>=1;}return u32(r);}
inline bool isprime(u32 n){if(n<2)return false;for(u32 a:{2u,3u,5u,7u})if(n%a==0)return n==a;u32 d=n-1,s=0;while(!(d&1)){d>>=1;++s;}
    for(u32 a:{2u,3u,5u,7u}){u64 x=pw(a,d,n);if(x==1||x==n-1)continue;bool ok=false;for(u32 r=1;r<s;++r){x=x*x%n;if(x==n-1){ok=true;break;}}if(!ok)return false;}return true;}
inline u32 brev16(u32 j){u32 r=0;for(int b=0;b<16;++b)r|=((j>>b)&1u)<<(15-b);return r;}
inline double local(const char* k){for(const J1DLocal& l:J1D_LOCAL)if(std::strcmp(l.key,k)==0)return l.v;return -1.0;}
}
template<class C> void run_j1_diag(C& d){
    using namespace j1d;
    if(const char* e=std::getenv("FHERMA_J1_DIAG"))if(std::atoi(e)==0)return;
    const auto t0=std::chrono::steady_clock::now();
    auto& dr=d.driver;
#define J1G(f,s) auto f=dr.template get<decltype(&::s)>(#s)
    J1G(devget,cuDeviceGet);J1G(attr,cuDeviceGetAttribute);J1G(dname,cuDeviceGetName);J1G(dver,cuDriverGetVersion);
    J1G(fattr,cuFuncGetAttribute);J1G(occf,cuOccupancyMaxActiveBlocksPerMultiprocessor);
    J1G(mload,cuModuleLoadData);J1G(mget,cuModuleGetFunction);J1G(munload,cuModuleUnload);
    J1G(mset,cuMemsetD8_v2);J1G(h2d,cuMemcpyHtoD_v2);J1G(d2h,cuMemcpyDtoH_v2);J1G(launch,cuLaunchKernel);J1G(sync,cuCtxSynchronize);
    J1G(screate,cuStreamCreate);J1G(sdestroy,cuStreamDestroy_v2);J1G(ecreate,cuEventCreate);J1G(edestroy,cuEventDestroy_v2);
    J1G(erecord,cuEventRecord);J1G(esync,cuEventSynchronize);J1G(etime,cuEventElapsedTime);J1G(swait,cuStreamWaitEvent);
    auto malloc_=dr.template get<decltype(&::cuMemAlloc_v2)>("cuMemAlloc_v2");auto mfree=dr.template get<decltype(&::cuMemFree_v2)>("cuMemFree_v2");
#undef J1G
    CUdevice dev=0;if(devget(&dev,0)!=CUDA_SUCCESS)return;
    int mj=0,mn=0,sms=0,clk=0,drv=0;char name[128]={0};
    attr(&mj,CU_DEVICE_ATTRIBUTE_COMPUTE_CAPABILITY_MAJOR,dev);attr(&mn,CU_DEVICE_ATTRIBUTE_COMPUTE_CAPABILITY_MINOR,dev);
    attr(&sms,CU_DEVICE_ATTRIBUTE_MULTIPROCESSOR_COUNT,dev);attr(&clk,CU_DEVICE_ATTRIBUTE_CLOCK_RATE,dev);dname(name,127,dev);dver(&drv);
    for(char* c=name;*c;++c)if(*c=='"'||*c=='\\')*c='_';
    if(sync()!=CUDA_SUCCESS)return;
    CUmodule mod=nullptr,modp=nullptr;CUresult lr=mload(&mod,J1D_PTX);CUresult lp=lr==CUDA_SUCCESS?mload(&modp,J1D_PTX_PROBE):lr;
    CUfunction fF=nullptr,fR=nullptr,fI=nullptr,fFill=nullptr,fSum=nullptr,pF=nullptr,pR=nullptr,pI=nullptr;
    if(lr==CUDA_SUCCESS&&(mget(&fF,mod,"j1_colfwd")||mget(&fR,mod,"j1_row")||mget(&fI,mod,"j1_colinv")||mget(&fFill,mod,"j1d_fill")||mget(&fSum,mod,"j1d_sum")))lr=CUDA_ERROR_NOT_FOUND;
    if(lp==CUDA_SUCCESS&&(mget(&pF,modp,"j1_colfwd")||mget(&pR,modp,"j1_row")||mget(&pI,modp,"j1_colinv")))lp=CUDA_ERROR_NOT_FOUND;
    int rg[3]={0,0,0},oc[3]={0,0,0};
    if(lr==CUDA_SUCCESS){CUfunction fs[3]={fF,fR,fI};for(int i=0;i<3;++i){fattr(&rg[i],CU_FUNC_ATTRIBUTE_NUM_REGS,fs[i]);occf(&oc[i],fs[i],128,0);}}
    std::printf("{\"diag\":\"j1ntt\",\"k\":\"info\",\"dev\":\"%s\",\"cc\":\"%d.%d\",\"sms\":%d,\"clock_khz\":%d,\"driver\":%d,\"load\":%d,\"load_probe\":%d,"
        "\"regs_fwd_row_inv\":[%d,%d,%d],\"blocks_per_sm\":[%d,%d,%d],\"local_regs\":[64,64,64],\"local_blocks_per_sm\":[8,8,8]}\n",
        name,mj,mn,sms,clk,drv,int(lr),int(lp),rg[0],rg[1],rg[2],oc[0],oc[1],oc[2]);std::fflush(stdout);
    if(lr!=CUDA_SUCCESS){if(mod)munload(mod);if(modp)munload(modp);return;}
    // host tables: the 118 largest primes p = 1 mod 2^17 below 2^30, psi = smallest g >= 2 with x = g^((p-1)/2N), x^N = -1
    const u32 N=65536u,K=118u;
    std::vector<u32> primes;for(u32 c=((1u<<30)-2u)/(1u<<17)*(1u<<17)+1u;primes.size()<K;c-=1u<<17)if(isprime(c))primes.push_back(c);
    std::vector<u32> pinv(K),thi(K*512);std::vector<u64> tw1(K*512),tlo(K*512);
    for(u32 k=0;k<K;++k){const u32 p=primes[k];u32 ps=0;for(u64 g=2;;++g){u32 x=pw(g,(p-1)/(2*N),p);if(pw(x,N,p)==p-1){ps=x;break;}}
        u32 iv=p;for(int i=0;i<5;++i)iv*=2u-p*iv;pinv[k]=0u-iv;const u32 pi=pw(ps,p-2,p);
        for(u32 dd=0;dd<2;++dd){const u32 g=dd?pi:ps;
            for(u32 j=0;j<256;++j){u32 w=pw(g,brev16(j),p);tw1[k*512+dd*256+j]=u64(w)|(((u64(w)<<32)/p)<<32);}
            for(u32 i=0;i<256;++i){thi[k*512+dd*256+i]=pw(g,256ull*i,p);u32 w=pw(g,i,p);tlo[k*512+dd*256+i]=u64((u128(w)<<64)/p);}}}
    std::vector<CUdeviceptr> bufs;bool okb=true;
    auto al=[&](size_t nb)->CUdeviceptr{CUdeviceptr p=0;if(malloc_(&p,nb)!=CUDA_SUCCESS){okb=false;return 0;}bufs.push_back(p);return p;};
    const size_t AW=size_t(K)*N*4;
    CUdeviceptr A0=al(AW),B0=al(AW),A1=al(AW),B1=al(AW),dP=al(K*4),dPi=al(K*4),dT1=al(K*4096),dTh=al(K*2048),dTl=al(K*4096),dS=al(64);
    CUstream s0=nullptr,s1=nullptr;CUevent ev[4]={nullptr,nullptr,nullptr,nullptr};
    if(okb){h2d(dP,primes.data(),K*4);h2d(dPi,pinv.data(),K*4);h2d(dT1,tw1.data(),K*4096);h2d(dTh,thi.data(),K*2048);h2d(dTl,tlo.data(),K*4096);}
    bool evok=true;for(auto& e:ev)if(ecreate(&e,0)!=CUDA_SUCCESS)evok=false;
    if(!okb||!evok||screate(&s0,CU_STREAM_NON_BLOCKING)!=CUDA_SUCCESS||screate(&s1,CU_STREAM_NON_BLOCKING)!=CUDA_SUCCESS){
        std::printf("{\"diag\":\"j1ntt\",\"error\":\"alloc\"}\n");std::fflush(stdout);
        for(auto p:bufs)mfree(p);for(auto e:ev)if(e)edestroy(e);if(s0)sdestroy(s0);if(s1)sdestroy(s1);munload(mod);if(modp)munload(modp);return;}
    bool bad=false;
    auto L=[&](CUfunction f,u32 gx,u32 gy,u32 gz,u32 sm,CUstream s,void** a){if(!bad&&launch(f,gx,gy,gz,128,1,1,sm,s,a,nullptr)!=CUDA_SUCCESS)bad=true;};
    auto fill=[&](CUdeviceptr X,u32 seed,CUstream s){u32 kk=K;void* a[]={&X,&dP,&kk,&seed};if(!bad&&launch(fFill,u32(sms)*8,1,1,256,1,1,0,s,a,nullptr)!=CUDA_SUCCESS)bad=true;};
    // which: 1 colfwd(a,b), 2 row, 4 colinv; dyn = dynamic smem per block (half occupancy)
    const u32 full[3]={0,0,0};
    auto chain=[&](CUfunction F,CUfunction R,CUfunction I,u32 KK,CUdeviceptr A,CUdeviceptr B,int which,const u32* dyn,CUstream s){
        if(which&1){void* a[]={&A,&B,&A,&B,&dP,&dT1};L(F,32,KK,2,dyn[0],s,a);}
        if(which&2){void* a[]={&A,&B,&A,&dP,&dPi,&dTh,&dTl};L(R,32,KK,1,dyn[1],s,a);}
        if(which&4){void* a[]={&A,&A,&dP,&dT1};L(I,32,KK,1,dyn[2],s,a);}};
    // dynamic smem that leaves 4 blocks per SM (4 warps per SMSP) for each kernel
    u32 half[3]={0,0,0};int hocc[3]={0,0,0};
    {CUfunction fs[3]={fF,fR,fI};for(int i=0;i<3;++i){for(u32 dyn=0;dyn<=48u*1024u;dyn+=512u){int o=0;occf(&o,fs[i],128,dyn);if(o<=4){half[i]=dyn;hocc[i]=o;break;}}}}
    const u32 ITERS=10;
    auto timed=[&](auto body)->double{double best=-1;for(int r=0;r<4&&!bad;++r){erecord(ev[0],s0);for(u32 i=0;i<ITERS;++i)body();erecord(ev[1],s0);
            if(esync(ev[1])!=CUDA_SUCCESS){bad=true;break;}float ms=0;etime(&ms,ev[0],ev[1]);double us=ms*1e3/ITERS;if(r&&(best<0||us<best))best=us;}return best;};   // r = 0: warm-up
    auto ln=[&](const char* k,u32 KK,u32 prods,double us,const char* extra){if(bad)return;const double cpp=us*clk*1e-3*4.0*sms/(double(KK)*N*prods);
        char lk[96];std::snprintf(lk,96,"%s",k);const double lu=local(lk);char lc[96];std::snprintf(lc,96,"%s.cpp",k);
        std::printf("{\"diag\":\"j1ntt\",\"k\":\"%s\",\"K\":%u,\"products\":%u,\"us\":%.2f,\"cyc_per_pt\":%.3f,\"local_us\":%.2f,\"local_cyc_per_pt\":%.3f%s}\n",k,KK,prods,us,cpp,lu,local(lc),extra);std::fflush(stdout);};
    fill(A0,1u,s0);fill(B0,2u,s0);fill(A1,3u,s0);fill(B1,4u,s0);if(sync()!=CUDA_SUCCESS)bad=true;
    // correctness: one chain from seeded inputs, checksum of y (= A0)
    {chain(fF,fR,fI,K,A0,B0,7,full,s0);mset(dS,0,8);u32 n=K*N;void* a[]={&A0,&n,&dS};if(!bad&&launch(fSum,u32(sms)*8,1,1,256,1,1,0,s0,a,nullptr)!=CUDA_SUCCESS)bad=true;
     if(sync()!=CUDA_SUCCESS)bad=true;unsigned long long cs=0;d2h(&cs,dS,8);
     if(!bad){std::printf("{\"diag\":\"j1ntt\",\"k\":\"check\",\"K\":%u,\"checksum\":\"%016llx\",\"local_checksum\":\"%s\",\"match\":%d}\n",K,cs,J1D_LOCAL_CHECKSUM,
         std::strtoull(J1D_LOCAL_CHECKSUM,nullptr,16)==cs?1:0);std::fflush(stdout);}}
    // (a) one product, two products in flight (two streams, one chain each)
    ln("chain_k118",K,1,timed([&]{chain(fF,fR,fI,K,A0,B0,7,full,s0);}),"");
    ln("chain_k118_x2",K,2,timed([&]{erecord(ev[2],s0);swait(s1,ev[2],0);chain(fF,fR,fI,K,A0,B0,7,full,s0);chain(fF,fR,fI,K,A1,B1,7,full,s1);erecord(ev[3],s1);swait(s0,ev[3],0);}),"");
    // (b) K = 32
    ln("chain_k32",32,1,timed([&]{chain(fF,fR,fI,32,A0,B0,7,full,s0);}),"");
    // (c) kernels alone, (d) arithmetic-removed probe, (e) half occupancy
    const char* kn[3]={"colfwd","row","colinv"};
    for(int i=0;i<3;++i){char k[64];std::snprintf(k,64,"%s_k118",kn[i]);ln(k,K,1,timed([&]{chain(fF,fR,fI,K,A0,B0,1<<i,full,s0);}),"");}
    if(lp==CUDA_SUCCESS){ln("probe_chain_k118",K,1,timed([&]{chain(pF,pR,pI,K,A0,B0,7,full,s0);}),"");
        for(int i=0;i<3;++i){char k[64];std::snprintf(k,64,"probe_%s_k118",kn[i]);ln(k,K,1,timed([&]{chain(pF,pR,pI,K,A0,B0,1<<i,full,s0);}),"");}}
    {char ex[160];std::snprintf(ex,160,",\"dyn_smem\":[%u,%u,%u],\"blocks_per_sm\":[%d,%d,%d]",half[0],half[1],half[2],hocc[0],hocc[1],hocc[2]);
     ln("half_chain_k118",K,1,timed([&]{chain(fF,fR,fI,K,A0,B0,7,half,s0);}),ex);
     for(int i=0;i<3;++i){char k[64];std::snprintf(k,64,"half_%s_k118",kn[i]);ln(k,K,1,timed([&]{chain(fF,fR,fI,K,A0,B0,1<<i,half,s0);}),ex);}}
    if(bad){std::printf("{\"diag\":\"j1ntt\",\"error\":\"launch\"}\n");std::fflush(stdout);}
    sync();for(auto p:bufs)mfree(p);for(auto e:ev)edestroy(e);sdestroy(s0);sdestroy(s1);munload(mod);if(modp)munload(modp);
    std::printf("{\"diag\":\"j1ntt\",\"k\":\"done\",\"s\":%.2f}\n",std::chrono::duration<double>(std::chrono::steady_clock::now()-t0).count());std::fflush(stdout);
}
